package enc

import (
	"bytes"
	"encoding/json"
	"net"
	"reflect"
	"testing"

	"sip/pkg/sipmsg"

	"github.com/stretchr/testify/assert"
)

func Test_decoder_ReadMessage(t *testing.T) {
	tests := getTestCases()

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			d := NewDecoder(tt.conn)
			got, err := d.ReadMessage()
			if (err != nil) != tt.wantErr {
				t.Errorf("ReadMessage() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			gotBytes, err := json.Marshal(got)
			assert.Empty(t, err)
			wantBytes, err := json.Marshal(tt.want)
			assert.Empty(t, err)
			if !reflect.DeepEqual(gotBytes, wantBytes) {
				t.Errorf("ReadMessage() got = %v, want %v", got, tt.want)
			}
		})
	}
}

type testCase struct {
	name    string
	conn    net.Conn
	want    *sipmsg.GenericMessage
	wantErr bool
}

func getTestCases() []testCase {
	cases := make([]testCase, 0)
	cases = append(cases, getRegisterMsg())
	cases = append(cases, getNotImplementedMsg())
	cases = append(cases, getOKMsg())
	cases = append(cases, getUnauthorizedMsg())
	cases = append(cases, getAcceptedMsg())
	cases = append(cases, getSubscribeMsg())
	return cases
}

